/**
 * particles-custom.js
 * Soft dotfield that sits behind the page.
 * Easing: gentle, premium, fast enough.
 */
(function () {
  'use strict';
  var container = document.getElementById('particlesCanvas');
  if (!container || !window.matchMedia('(prefers-reduced-motion: no-preference)').matches) {
    if (container) container.style.display = 'none';
    return;
  }
  var ctx, w, h, dots = [], raf, dpr;
  var config = {
    count: 72,
    minDist: 64,
    linkAlpha: 0.10,
    dotRadius: 2.1,
    dotColor: 'rgba(58, 92, 133, 0.55)',
    dotHover: 'rgba(5, 150, 105, 0.75)',
    linkColor: 'rgba(58, 92, 133, 0.14)',
    moveSpeed: 0.18,
    respawnMargin: 120,
    pointerRadius: 180,
  };
  var mouse = { x: -9999, y: -9999, active: false };
  var pointer = { x: -9999, y: -9999 };

  function init() {
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    w = container.offsetWidth;
    h = container.offsetHeight;
    ctx = container.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    dots.length = 0;
    var spacing = Math.max(config.minDist * 1.15, 96);
    var cols = Math.max(1, Math.floor(w / spacing));
    var rows = Math.max(1, Math.floor(h / spacing));
    var perCol = Math.max(1, Math.ceil(config.count / (cols * rows * 0.8)));
    for (var r = 0; r < rows; r++) {
      for (var c = 0; c < cols; c++) {
        if (dots.length >= config.count) break;
        dots.push({
          x: (c + 0.5) * spacing + (Math.random() - 0.5) * spacing * 0.4,
          y: (r + 0.5) * spacing + (Math.random() - 0.5) * spacing * 0.4,
          vx: (Math.random() - 0.5) * 0.3,
          vy: (Math.random() - 0.5) * 0.3,
        });
      }
      if (dots.length >= config.count) break;
    }
    while (dots.length < config.count) {
      dots.push({
        x: Math.random() * w,
        y: Math.random() * h,
        vx: (Math.random() - 0.5) * 0.3,
        vy: (Math.random() - 0.5) * 0.3,
      });
    }
    loop();
  }

  function frame() {
    ctx.clearRect(0, 0, w, h);
    for (var i = 0; i < dots.length; i++) {
      var a = dots[i];
      a.x += a.vx;
      a.y += a.vy;
      if (a.x < -config.respawnMargin) a.x = w + config.respawnMargin;
      else if (a.x > w + config.respawnMargin) a.x = -config.respawnMargin;
      if (a.y < -config.respawnMargin) a.y = h + config.respawnMargin;
      else if (a.y > h + config.respawnMargin) a.y = -config.respawnMargin;
      a.vx += (Math.random() - 0.5) * 0.02;
      a.vy += (Math.random() - 0.5) * 0.02;
      var ps = 0.95;
      a.vx *= ps; a.vy *= ps;
      if (Math.abs(a.vx) > 0.6) a.vx *= 0.85;
      if (Math.abs(a.vy) > 0.6) a.vy *= 0.85;
    }
    if (mouse.active) {
      for (var i = 0; i < dots.length; i++) {
        var a = dots[i];
        var dx = a.x - mouse.x;
        var dy = a.y - mouse.y;
        var d = Math.sqrt(dx * dx + dy * dy);
        if (d < config.pointerRadius && d > 0.01) {
          var force = (config.pointerRadius - d) / config.pointerRadius;
          var push = force * force * 1.6;
          a.vx += (dx / d) * push;
          a.vy += (dy / d) * push;
        }
      }
    }
    ctx.lineWidth = 1;
    ctx.strokeStyle = config.linkColor;
    ctx.beginPath();
    var limit = Math.min(dots.length, config.count);
    for (var i = 0; i < limit; i++) {
      var a = dots[i];
      for (var j = i + 1; j < limit; j++) {
        var b = dots[j];
        var dx = a.x - b.x;
        var dy = a.y - b.y;
        var d = dx * dx + dy * dy;
        if (d < config.minDist * config.minDist) {
          var alpha = (1 - Math.sqrt(d) / config.minDist) * config.linkAlpha;
          ctx.globalAlpha = alpha;
          ctx.moveTo(a.x, a.y);
          ctx.lineTo(b.x, b.y);
        }
      }
    }
    ctx.stroke();
    ctx.globalAlpha = 1;
    ctx.fillStyle = config.dotColor;
    for (var i = 0; i < dots.length; i++) {
      var a = dots[i];
      ctx.globalAlpha = 0.35;
      ctx.beginPath();
      ctx.arc(a.x, a.y, config.dotRadius, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.fillStyle = config.dotHover;
    ctx.globalAlpha = 0.0;
    for (var i = 0; i < dots.length; i++) {
      var a = dots[i];
      var dx = a.x - pointer.x;
      var dy = a.y - pointer.y;
      if (!mouse.active) continue;
      var d = Math.sqrt(dx * dx + dy * dy);
      if (d < config.pointerRadius * 0.5) {
        ctx.globalAlpha = Math.max(0, 1 - d / (config.pointerRadius * 0.5)) * 0.5;
        ctx.beginPath();
        ctx.arc(a.x, a.y, config.dotRadius * 1.6, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.globalAlpha = 0.35;
    ctx.globalCompositeOperation = 'lighter';
    raf = requestAnimationFrame(frame);
  }

  function loop() {
    if (raf) cancelAnimationFrame(raf);
    frame();
  }

  function onMove(e) {
    var t = e.touches ? e.touches[0] : e;
    mouse.x = t.clientX;
    mouse.y = t.clientY;
    mouse.active = true;
    pointer.x = t.clientX;
    pointer.y = t.clientY;
  }
  function onLeave() {
    mouse.active = false;
    mouse.x = -9999; mouse.y = -9999;
  }
  function onResize() {
    var ow = container.offsetWidth;
    var oh = container.offsetHeight;
    if (ow === w && oh === h) return;
    ctx = null;
    w = container.offsetWidth;
    h = container.offsetHeight;
    ctx = container.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  if (!container) return;
  if (typeof ResizeObserver !== 'undefined') {
    try { new ResizeObserver(onResize).observe(container); } catch (_) {}
  }
  window.addEventListener('mousemove', onMove, { passive: true });
  window.addEventListener('mouseleave', onLeave);
  window.addEventListener('touchmove', onMove, { passive: true });
  window.addEventListener('touchend', onLeave);
  window.addEventListener('resize', onResize);
  init();
  if (typeof document !== 'undefined' && document.readyState === 'complete') {
    // re-paint after layout settles
    setTimeout(init, 60);
  }
})();
